import pytest
import asyncio
import json
from unittest.mock import AsyncMock, MagicMock, patch
from main import main

# --- Mock Data Models ---
class MockFinding:
    """Simulates a Finding object returned by the ScanEngine."""
    def __init__(self, plugin_id, severity_name, title, description, evidence, remediation):
        self.plugin_id = plugin_id
        self.severity = MagicMock()
        self.severity.name = severity_name
        self.title = title
        self.description = description
        self.evidence = evidence
        self.remediation = remediation

@pytest.fixture
def mock_findings():
    """Provides a standard set of mock findings for validation."""
    return [
        MockFinding(
            "port_scanner", "MEDIUM", "Open Port 22", 
            "SSH port is open", "Port 22/tcp open", "Restrict SSH access"
        ),
        MockFinding(
            "http_audit", "LOW", "Missing X-Frame-Options", 
            "Clickjacking vulnerability", "Header missing", "Add X-Frame-Options header"
        )
    ]

@pytest.mark.asyncio
async def test_main_execution_flow(mock_findings):
    """
    Validates the end-to-end orchestration flow: 
    Engine Init -> Plugin Registration -> Scan Execution -> JSON Transformation.
    """
    with patch('main.ScanEngine') as MockEngine, \
         patch('main.PortScannerPlugin') as MockPortPlugin, \
         patch('main.HTTPHeaderAuditPlugin') as MockHTTPPlugin, \
         patch('builtins.print') as mock_print:

        # Setup Mock Engine Instance
        mock_engine_instance = MockEngine.return_value
        mock_engine_instance.scan = AsyncMock(return_value=mock_findings)
        mock_engine_instance.register_plugin = MagicMock()

        # Execute the target function
        await main()

        # 1. Verify Engine Initialization
        MockEngine.assert_called_once_with(concurrency_limit=50)

        # 2. Verify Plugin Registration with correct configs
        # Check PortScannerPlugin registration
        mock_engine_instance.register_plugin.assert_any_call(
            MockPortPlugin, {"ports": [22, 80, 443, 8080], "timeout": 1.5}
        )
        # Check HTTPHeaderAuditPlugin registration
        mock_engine_instance.register_plugin.assert_any_call(
            MockHTTPPlugin, {"timeout": 5}
        )

        # 3. Verify Scan Execution
        mock_engine_instance.scan.assert_called_once_with("scanme.nmap.org")

        # 4. Verify Output Formatting
        # Capture the print call containing the JSON output
        args, _ = mock_print.call_args
        printed_output = args[0]
        
        # Parse the printed JSON string back to a list
        # The main function prints a header then the JSON
        json_str = "\n".join(mock_print.call_args_list[1][0][0].splitlines())
        parsed_results = json.loads(json_str)

        assert len(parsed_results) == 2
        assert parsed_results[0]["plugin"] == "port_scanner"
        assert parsed_results[0]["severity"] == "MEDIUM"
        assert parsed_results[1]["plugin"] == "http_audit"
        assert parsed_results[1]["title"] == "Missing X-Frame-Options"

