@pytest.mark.asyncio
async def test_main_engine_failure():
    """Validates system resilience when the ScanEngine raises an exception."""
    with patch('main.ScanEngine') as MockEngine:
        mock_engine_instance = MockEngine.return_value
        mock_engine_instance.scan = AsyncMock(side_effect=Exception("Network Timeout"))
        mock_engine_instance.register_plugin = MagicMock()

        with pytest.raises(Exception) as excinfo:
            await main()
        
        assert "Network Timeout" in str(excinfo.value)

@pytest.mark.asyncio
async def test_plugin_config_integrity():
    """Strict check on the configuration values passed to plugins."""
    with patch('main.ScanEngine') as MockEngine:
        mock_engine_instance = MockEngine.return_value
        mock_engine_instance.register_plugin = MagicMock()
        mock_engine_instance.scan = AsyncMock(return_value=[])

        await main()

        # Extract all calls to register_plugin
        calls = mock_engine_instance.register_plugin.call_args_list
        
        # Verify network config specifically
        network_call = next(call for call in calls if call[0][0] == 'main.PortScannerPlugin' or True) 
        # Note: In real mock, we check the class reference. 
        # Since we patched the classes, we check the arguments.
        
        # Verify that the config dictionary was passed exactly as defined in main.py
        configs_passed = [call[0][1] for call in calls]
        assert {"ports": [22, 80, 443, 8080], "timeout": 1.5} in configs_passed
        assert {"timeout": 5} in configs_passed